INSERT INTO cities (id, name, native_name, state, nickname, accent, stamp, poster, greeting, greeting_note, from_line, letter, quick_facts, sources, sort_order) VALUES
  ('udaipur', 'Udaipur', 'उदयपुर', 'Rajasthan', 'The City of Lakes', '#2b45a6', 'assets/stamp-udaipur.png', 'assets/poster-udaipur.jpg', 'Khamma Ghani!', 'a traditional Rajasthani greeting', 'Gaju, at the ghats of Lake Pichola',
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('udaipur', 'landmarks', 'Landmarks', '🏰', 0);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'City Palace', 'Begun by Udai Singh II in the mid-1500s and added to by Maharanas for roughly 400 years, this complex of courtyards, towers and mirror-work halls rises above the east bank of Lake Pichola. It is one of the largest palace complexes in Rajasthan.', 'https://en.wikipedia.org/wiki/City_Palace,_Udaipur', 0),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'Lake Pichola', 'An artificial lake said to date from the late 1300s, long before the city existed, and later enlarged by Udai Singh II. Boats from the palace ghats still carry visitors out to its island palaces.', 'https://en.wikipedia.org/wiki/Lake_Pichola', 1),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'Lake Palace (Jag Niwas)', 'Built between 1743 and 1746 by Maharana Jagat Singh II as a summer palace on an island. Today it is a hotel that seems to float on the water.', 'https://en.wikipedia.org/wiki/Lake_Palace', 2),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'Jag Mandir', 'A second island palace. In the 1620s it sheltered Prince Khurram, who later became the Mughal emperor Shah Jahan, builder of the Taj Mahal.', 'https://en.wikipedia.org/wiki/Jag_Mandir_Palace', 3),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'Fateh Sagar Lake', 'First dammed in 1678 by Maharana Jai Singh, then rebuilt and renamed by Maharana Fateh Singh in the late 1800s. Nehru Park sits on the largest of its three islands.', 'https://en.wikipedia.org/wiki/Fateh_Sagar_Lake', 4),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'Sajjangarh (Monsoon Palace)', 'Built in 1884 by Maharana Sajjan Singh on a hilltop west of the city. It was first planned as an observatory for watching monsoon clouds, but he died before it was finished.', 'https://en.wikipedia.org/wiki/Monsoon_Palace', 5),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'landmarks'), 'Saheliyon-ki-Bari', 'The "Garden of the Maidens", laid out in the early 18th century by Maharana Sangram Singh II, with a lotus pool, marble elephants and fountains for the royal women.', 'https://en.wikipedia.org/wiki/Saheliyon-ki-Bari', 6);
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('udaipur', 'festivals', 'Festivals & Arts', '🪔', 1);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'festivals'), 'Mewar Festival', 'Held in spring during Gangaur. Women dress in their brightest clothes and carry idols of the goddess Gauri in procession to Gangaur Ghat, followed by music, dance and fireworks over Lake Pichola.', 'https://utsav.gov.in/view-event/mewar-festival', 0),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'festivals'), 'Shilpgram Utsav', 'A ten-day crafts fair every December at Shilpgram, a rural arts village outside the city where artisans from western India show their work.', 'https://en.wikipedia.org/wiki/Shilpgram,_Udaipur', 1),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'festivals'), 'Mewar miniature painting', 'A tradition of small, richly detailed paintings of court life, hunts and stories of Krishna, made with fine brushes and mineral colours.', 'https://mapacademy.io/article/mewar-school-of-painting/', 2),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'festivals'), 'Pichwai', 'Large cloth paintings made for the Shrinathji temple in nearby Nathdwara, showing Krishna with cows, lotuses and seasonal festivals.', 'https://en.wikipedia.org/wiki/Nathdwara_painting', 3),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'festivals'), 'Kathputli puppets', 'Rajasthan''s string puppets tell old stories of kings and heroes. Udaipur''s Bharatiya Lok Kala Mandal has a whole museum of them.', 'https://en.wikipedia.org/wiki/Bharatiya_Lok_Kala_Mandal', 4),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'festivals'), 'Dharohar dance show', 'An evening show, long held at Bagore ki Haveli, where dancers perform Rajasthani folk dances, including Bhavai, where a dancer balances a tall stack of pots on her head.', 'https://www.lonelyplanet.com/points-of-interest/dharohar/449475', 5);
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('udaipur', 'food', 'Food', '🍛', 2);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'food'), 'Dal Baati Churma', 'Hard wheat balls (baati) baked over fire, cracked open and soaked in ghee, eaten with spicy dal and sweet crumbled churma.', 'https://en.wikipedia.org/wiki/Rajasthani_cuisine', 0),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'food'), 'Gatte ki Sabzi', 'Gram-flour dumplings, boiled or steamed, in a tangy yoghurt curry. A good dish for a desert land where fresh vegetables were scarce.', 'https://en.wikipedia.org/wiki/Rajasthani_cuisine', 1),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'food'), 'Ker Sangri', 'A desert-bean and wild-berry dish cooked with spices. Both ingredients grow in the dry lands of Rajasthan.', 'https://en.wikipedia.org/wiki/Rajasthani_cuisine', 2),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'food'), 'Mirchi Vada', 'A big green chilli stuffed with spiced potato, dipped in gram-flour batter and fried. It comes from Jodhpur and is loved across Rajasthan.', 'https://en.wikipedia.org/wiki/Mirchi_bada', 3),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'food'), 'Laal Maas', 'A fiery red mutton curry made with Mathania chillies, linked to the hunting camps of Rajput royalty.', 'https://en.wikipedia.org/wiki/Laal_maas', 4);
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('udaipur', 'facts', 'Fun Facts', '✨', 3);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'facts'), 'A Bond film was shot here', 'The 1983 James Bond film Octopussy used the Lake Palace and the Monsoon Palace as filming locations.', 'https://www.jamesbondlifestyle.com/node/919', 0),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'facts'), 'Maharana Pratap', 'Mewar''s most famous ruler fought the Mughal army led by Man Singh at the Battle of Haldighati in 1576, in the hills north of Udaipur.', 'https://en.wikipedia.org/wiki/Battle_of_Haldighati', 1),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'facts'), 'The sun on the walls', 'The Mewar rulers traced their line to the sun god, so a huge ornamental sun shines in the Surya Chopar (Sun Square) of the City Palace.', 'https://www.lonelyplanet.com/articles/guide-to-city-palace-udaipur', 2),
  ((SELECT id FROM sections WHERE city_id = 'udaipur' AND slug = 'facts'), 'Lakes that talk to each other', 'Lake Pichola and Fateh Sagar are linked through the smaller Swaroop Sagar lake and a canal, so water can flow between them.', 'https://en.wikipedia.org/wiki/Swaroop_Sagar_Lake', 3);
INSERT INTO quiz_questions (city_id, question, options, answer_index, sort_order) VALUES
  ('udaipur', 'Who founded Udaipur in 1559?', '["Maharana Pratap","Maharana Udai Singh II","Maharana Sajjan Singh","Akbar"]'::jsonb, 1, 0),
  ('udaipur', 'Which lake is the Lake Palace (Jag Niwas) built in?', '["Fateh Sagar","Lake Pichola","Dal Lake","Hussain Sagar"]'::jsonb, 1, 1),
  ('udaipur', 'What is Sajjangarh also called?', '["Monsoon Palace","Wind Palace","Mirror Palace","Water Palace"]'::jsonb, 0, 2),
  ('udaipur', 'Which James Bond film was shot in Udaipur?', '["Skyfall","Goldfinger","Octopussy","Dr. No"]'::jsonb, 2, 3),
  ('udaipur', 'Dal Baati Churma: what is the "baati"?', '["A sweet syrup","A baked wheat ball","A lentil soup","A fried chilli"]'::jsonb, 1, 4);
INSERT INTO cities (id, name, native_name, state, nickname, accent, stamp, poster, greeting, greeting_note, from_line, letter, quick_facts, sources, sort_order) VALUES
  ('kolkata', 'Kolkata', 'কলকাতা', 'West Bengal', 'The City of Joy', '#b9503a', 'assets/stamp-kolkata.png', 'assets/poster-kolkata.jpg', 'Nomoshkar!', 'hello, in Bengali', 'Gaju, on the banks of the Hooghly',
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('kolkata', 'landmarks', 'Landmarks', '🏛️', 0);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'landmarks'), 'Victoria Memorial', 'A huge white marble hall, opened in 1921 in memory of Queen Victoria. It is now a museum, surrounded by gardens and ponds.', 'https://en.wikipedia.org/wiki/Victoria_Memorial,_Kolkata', 0),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'landmarks'), 'Howrah Bridge (Rabindra Setu)', 'A giant cantilever bridge over the Hooghly, opened in 1943. It is held together with rivets rather than nuts and bolts, and carries a huge flow of people and vehicles every day.', 'https://en.wikipedia.org/wiki/Howrah_Bridge', 1),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'landmarks'), 'Indian Museum', 'Founded in 1814, it is the oldest museum in India, with fossils, an Egyptian mummy and ancient sculptures.', 'https://en.wikipedia.org/wiki/Indian_Museum', 2),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'landmarks'), 'Dakshineswar Kali Temple', 'A riverside temple built by Rani Rashmoni and opened in 1855. The saint Ramakrishna served as its priest and taught here.', 'https://en.wikipedia.org/wiki/Dakshineswar_Kali_Temple', 3),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'landmarks'), 'Kumartuli', 'The potters'' quarter on the river, where families of artists shape the clay idols of Durga every year by hand.', 'https://en.wikipedia.org/wiki/Kumortuli', 4),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'landmarks'), 'College Street (Boi Para)', 'The "book neighbourhood": a long stretch of second-hand bookstalls beside famous colleges and the Indian Coffee House.', 'https://en.wikipedia.org/wiki/College_Street,_Kolkata', 5);
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('kolkata', 'festivals', 'Festivals & Arts', '🪔', 1);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'festivals'), 'Durga Puja', 'Kolkata''s biggest festival. Artists build thousands of themed pandals (temporary shrines) for the goddess Durga. In 2021 UNESCO added Durga Puja in Kolkata to its list of the Intangible Cultural Heritage of Humanity.', 'https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703', 0),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'festivals'), 'Dhunuchi naach and sindoor khela', 'During Puja, dancers swing clay pots of smoking incense, and on the last day married women smear each other with red sindoor.', 'https://en.wikipedia.org/wiki/Dhunuchi_Nritya', 1),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'festivals'), 'International Kolkata Book Fair', 'Held every winter since 1976, it is one of the biggest book fairs in the world by number of visitors.', 'https://en.wikipedia.org/wiki/Kolkata_Book_Fair', 2),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'festivals'), 'Rabindra Sangeet', 'The songs written by Rabindranath Tagore, more than two thousand of them, still sung across Bengal.', 'https://en.wikipedia.org/wiki/Rabindra_Sangeet', 3),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'festivals'), 'Kalighat painting', 'Bold, quick-brush paintings that began in the 19th century near the Kalighat temple, showing gods and everyday city life.', 'https://en.wikipedia.org/wiki/Kalighat_painting', 4);
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('kolkata', 'food', 'Food', '🍛', 2);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'food'), 'Rosogolla', 'Soft cheese balls in sugar syrup. In 2017 West Bengal received a GI tag for "Banglar Rosogolla".', 'https://moneylife.in/article/tag-only-for-banglar-rasogolloa-not-for-the-sweet-in-general-gi-registry/52187.html', 0),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'food'), 'Mishti Doi', 'Sweet yoghurt set in clay pots, which soak up extra water and make it thick.', 'https://en.wikipedia.org/wiki/Mishti_doi', 1),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'food'), 'Phuchka', 'Kolkata''s version of pani puri: crisp shells filled with spiced potato and tangy tamarind water.', 'https://en.wikipedia.org/wiki/Panipuri', 2),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'food'), 'Kathi Roll', 'Kebabs wrapped in a flaky paratha. It is usually traced to Nizam''s restaurant in Kolkata and is now eaten all over India.', 'https://www.atlasobscura.com/articles/the-kati-roll-can-be-traced-back-to-one-kolkata-restaurant', 3),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'food'), 'Shorshe Ilish', 'Hilsa fish cooked in a sharp mustard sauce, a Bengali favourite during the monsoon.', 'https://en.wikipedia.org/wiki/Shorshe_ilish', 4),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'food'), 'Kolkata Biryani', 'Lighter than other biryanis and famous for its potato, linked to the cooks of Nawab Wajid Ali Shah, who settled in the city in 1856.', 'https://www.sahapedia.org/the-kolkata-biryani-culture-identity-and-politics', 5);
INSERT INTO sections (city_id, slug, label, icon, sort_order) VALUES ('kolkata', 'facts', 'Fun Facts', '✨', 3);
INSERT INTO facts (section_id, title, body, source_url, sort_order) VALUES
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'facts'), 'India''s first metro', 'India''s first metro railway opened in Kolkata in 1984. In 2024 the city also opened India''s first underwater metro tunnel, under the Hooghly.', 'https://en.wikipedia.org/wiki/Kolkata_Metro', 0),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'facts'), 'Trams since 1873', 'Kolkata''s trams began in 1873, pulled by horses, and became electric in 1902. It is the only Indian city that kept its trams into the 21st century, though only a couple of routes still run.', 'https://en.wikipedia.org/wiki/Trams_in_Kolkata', 1),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'facts'), 'A first for Asia', 'Rabindranath Tagore, born in Kolkata, won the Nobel Prize in Literature in 1913, the first for anyone from outside Europe. He also wrote India''s national anthem.', 'https://www.britannica.com/biography/Rabindranath-Tagore', 2),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'facts'), 'An Oscar for Ray', 'Kolkata filmmaker Satyajit Ray received an honorary Academy Award in 1992 for his lifetime of work.', 'https://en.wikipedia.org/wiki/Satyajit_Ray', 3),
  ((SELECT id FROM sections WHERE city_id = 'kolkata' AND slug = 'facts'), 'Yellow taxis', 'The yellow Ambassador taxi became a symbol of the city. Old ones are now being retired under a 15-year age limit.', 'https://www.outlooktraveller.com/experiences/culture/after-trams-will-kolkatas-iconic-yellow-ambassador-taxi-ride-into-the-sunset', 4);
INSERT INTO quiz_questions (city_id, question, options, answer_index, sort_order) VALUES
  ('kolkata', 'Which river does Kolkata stand on?', '["Yamuna","Hooghly","Godavari","Narmada"]'::jsonb, 1, 0),
  ('kolkata', 'In which year did UNESCO recognise Durga Puja in Kolkata?', '["2001","2011","2017","2021"]'::jsonb, 3, 1),
  ('kolkata', 'Howrah Bridge is also called…', '["Vidyasagar Setu","Rabindra Setu","Ram Setu","Bandra Setu"]'::jsonb, 1, 2),
  ('kolkata', 'Kolkata was the capital of British India until…', '["1857","1911","1947","1950"]'::jsonb, 1, 3),
  ('kolkata', 'Where did India''s first metro railway open, in 1984?', '["Delhi","Mumbai","Kolkata","Chennai"]'::jsonb, 2, 4);
